/**
 * User-authored cursor skin. The shipped art is the built-in whale sprite:
 * states the user has not uploaded keep rendering the whale (an invalid
 * placeholder data URI here would fail the img load, flip the follower's
 * error gate, and silently revert the whole custom skin to the OS cursor).
 * Runtime uploads overlay per-state data URLs from localStorage
 * ({@link readCursorUploads}); the merged skin never mutates either base map.
 */
export const CUSTOM_CURSOR_STATES: Record<string, CursorState> = { ...CURSOR_STATES }

/** All selectable cursor skins keyed by {@link CursorSkinId}. */
export const CURSOR_SKINS: Record<CursorSkinId, Record<string, CursorState>> = {
  whale: CURSOR_STATES,
  custom: CUSTOM_CURSOR_STATES,
}

/** localStorage key holding user-uploaded cursor images (state -> data URL). */
export const CURSOR_UPLOAD_KEY = 'dsh-beautify:cursor-uploads'

/** State ids in upload order with a display label for the settings UI. */
export const CURSOR_UPLOAD_STATES: ReadonlyArray<{ id: string; label: string }> = [
  { id: 'default', label: '默认箭头' },
  { id: 'link', label: '链接手型' },
  { id: 'text', label: '文本' },
  { id: 'busy', label: '忙碌' },
  { id: 'not-allowed', label: '禁止' },
  { id: 'precision', label: '十字准星' },
  { id: 'background', label: '背景' },
  { id: 'pen', label: '画笔' },
  { id: 'help', label: '帮助' },
  { id: 'drag', label: '拖动' },
]

/** User-uploaded cursor images persisted in localStorage (state id -> data URL). */
export type CursorUploads = Partial<Record<string, string>>

/** Read uploaded cursor images, tolerating missing or malformed storage. */
export function readCursorUploads(): CursorUploads {
  try {
    const raw = localStorage.getItem(CURSOR_UPLOAD_KEY)
    if (raw === null) return {}
    const parsed = JSON.parse(raw) as CursorUploads
    if (typeof parsed !== 'object' || parsed === null) return {}
    const out: CursorUploads = {}
    for (const [state, dataUrl] of Object.entries(parsed)) {
      if (typeof dataUrl === 'string' && dataUrl.startsWith('data:image/')) out[state] = dataUrl
    }
    return out
  } catch {
    return {}
  }
}

/** Persist uploaded cursor images. */
export function writeCursorUploads(uploads: CursorUploads): void {
  try {
    localStorage.setItem(CURSOR_UPLOAD_KEY, JSON.stringify(uploads))
  } catch {
    // Storage full or unavailable; the in-memory skin still works this session.
  }
}

/** Resolve a skin by id, falling back to the built-in whale skin. */
export function cursorSkinFor(id: string | undefined): Record<string, CursorState> {
  if (id === 'custom') {
    // Overlay user uploads onto the placeholder art so un-uploaded states
    // still render (they keep the whale fallback until replaced).
    const uploads = readCursorUploads()
    if (Object.keys(uploads).length === 0) return CUSTOM_CURSOR_STATES
    const merged: Record<string, CursorState> = {}
    for (const [state, next] of Object.entries(CUSTOM_CURSOR_STATES)) {
      const uploaded = uploads[state]
      merged[state] = uploaded !== undefined
        ? { ...next, image: uploaded }
        : next
    }
    return merged
  }
  return CURSOR_STATES
}
